        return {(a,c) for a,b in L for b2,c in R if b==b2}
    if tag == "alt":  return brute(tree[1],E,nodes) | brute(tree[2],E,nodes)
    if tag == "zeroone": return brute(tree[1],E,nodes) | {(n,n) for n in nodes}
    if tag in ("oneplus","zero"):
