    def _next_path(self, i: int, ch: str, text: str, n: int) -> _Token:
        simple = {
            "{": _TOK_LBRACE,
            "}": _TOK_RBRACE,
            ".": _TOK_DOT,
            "*": _TOK_STAR,
            "(": _TOK_LPAREN,
            ")": _TOK_RPAREN,
            "^": _TOK_HAT,
            "/": _TOK_SLASH,
            "|": _TOK_PIPE,
            "+": _TOK_PLUS,
