                while j < n and _is_var_char(text[j]):
                    j += 1
                self.pos = j
                return _Token(_TOK_VAR, text[i:j], i)
            self.pos = i + 1
            return _Token(_TOK_QUESTION, "?", i)
        if ch == '"':
            return self._next_string(i, text, n)
